import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for {@link FDistribution#isSupportLowerBoundInclusive()}.
 */
public class FDistribution_isSupportLowerBoundInclusive_TriageGen2Test {

    @Test
    public void testIsSupportLowerBoundInclusive() {
        // Given: A valid FDistribution instance
        // F-distribution is defined for x > 0, but the method is expected to return true 
        // indicating the lower bound is inclusive in terms of the support property.
        double numeratorDegreesOfFreedom = 5.0;
        double denominatorDegreesOfFreedom = 10.0;
        FDistribution distribution = new FDistribution(numeratorDegreesOfFreedom, denominatorDegreesOfFreedom);

        // When: Calling isSupportLowerBoundInclusive
        boolean result = distribution.isSupportLowerBoundInclusive();

        // Then: The result should be true
        Assert.assertTrue("isSupportLowerBoundInclusive should return true for FDistribution", result);
    }


}

package org.apache.commons.math3.distribution;

